SELECT 
     A.Account_Basic_Number_External AS Customer_Number
    ,C.Customer_Name
    ,A.Account_Number
    ,A.Account_Number_External
	,pr.Product_Description
    ,a.Balance_Sheet_Code
    ,b.Balance_Sheet_Description
    --,SUM(CASE WHEN Account_Balance_Date BETWEEN '2025-01-01' AND '2025-01-31' THEN Balance_Last_Business_Day_Local ELSE 0 END) / 31 AS AVG_JAN
    --,SUM(CASE WHEN Account_Balance_Date BETWEEN '2025-02-01' AND '2025-02-28' THEN Balance_Last_Business_Day_Local ELSE 0 END) / 28 AS AVG_FEB
    --,SUM(CASE WHEN Account_Balance_Date BETWEEN '2025-03-01' AND '2025-03-31' THEN Balance_Last_Business_Day_Local ELSE 0 END) / 31 AS AVG_MAR
    --,SUM(CASE WHEN Account_Balance_Date BETWEEN '2025-04-01' AND '2025-04-30' THEN Balance_Last_Business_Day_Local ELSE 0 END) / 30 AS AVG_APR
    --,SUM(CASE WHEN Account_Balance_Date BETWEEN '2025-05-01' AND '2025-05-31' THEN Balance_Last_Business_Day_Local ELSE 0 END) / 31 AS AVG_MAY
    --,SUM(CASE WHEN Account_Balance_Date BETWEEN '2025-06-01' AND '2025-06-30' THEN Balance_Last_Business_Day_Local ELSE 0 END) / 30 AS AVG_JUN
    --,SUM(CASE WHEN Account_Balance_Date BETWEEN '2025-07-01' AND '2025-07-31' THEN Balance_Last_Business_Day_Local ELSE 0 END) / 31 AS AVG_JUL
    --,SUM(CASE WHEN Account_Balance_Date BETWEEN '2025-08-01' AND '2025-08-31' THEN Balance_Last_Business_Day_Local ELSE 0 END) / 31 AS AVG_AUG
    --,SUM(CASE WHEN Account_Balance_Date BETWEEN '2025-09-01' AND '2025-09-30' THEN Balance_Last_Business_Day_Local ELSE 0 END) / 30 AS AVG_SEP
    --,SUM(CASE WHEN Account_Balance_Date BETWEEN '2025-10-01' AND '2025-10-31' THEN Balance_Last_Business_Day_Local ELSE 0 END)/31 AS AVG_OCT
    --,SUM(CASE WHEN Account_Balance_Date BETWEEN '2025-11-01' AND '2025-11-30' THEN Balance_Last_Business_Day_Local ELSE 0 END)/30 AS AVG_NOV
    --,SUM(CASE WHEN Account_Balance_Date BETWEEN '2025-12-01' AND '2025-12-31' THEN Balance_Last_Business_Day_Local ELSE 0 END)/31 AS AVG_DEC
	--,SUM(CASE WHEN Account_Balance_Date BETWEEN '2026-01-01' AND '2026-01-31' THEN Balance_Last_Business_Day_Local ELSE 0 END)/31 AS MTD_AVG_JAN_26
	,SUM(CASE WHEN Account_Balance_Date BETWEEN '2026-04-01' AND '2026-04-30' THEN Balance_Last_Business_Day_Local ELSE 0 END)/30 AS MTD_AVG_APR_26
	--,SUM(CASE WHEN Account_Balance_Date BETWEEN '2026-03-01' AND '2026-03-31' THEN Balance_Last_Business_Day_Local ELSE 0 END)/31 AS MTD_AVG_MAR_26
	--,SUM(CASE WHEN Account_Balance_Date BETWEEN '2026-01-01' AND '2026-02-28' THEN Balance_Last_Business_Day_Local ELSE 0 END)/59 AS YTD_AVG_FEB_26
	,SUM(CASE WHEN Account_Balance_Date BETWEEN '2026-01-01' AND '2026-04-30' THEN Balance_Last_Business_Day_Local ELSE 0 END)/120 AS YTD_AVG_26

    FROM Equation_Presentation..F_Account_Balance A
    INNER JOIN Equation_Presentation..D_Customer C 
    ON C.Customer_Number = A.Account_Basic_Number
    LEFT JOIN Equation_Presentation..D_Balance_Sheet B 
    ON A.Balance_Sheet_Code = B.Balance_Sheet_Code
    LEFT JOIN Equation_Presentation..D_PBG_Customer PB 
    ON A.Account_Basic_Number = PB.Customer_Number
    LEFT JOIN Equation_Presentation..D_Product PR 
    ON PR.Product_Code = A.Balance_Sheet_Code
    WHERE Account_Balance_Date BETWEEN '2026-01-01' AND '2026-04-30'
